#!/usr/bin/env node
/**
 * Generate `src/entity_data.mbt` — the HTML5 named character reference table
 * CommonMark requires for entity references.
 *
 * Usage: node scripts/gen-entities.js
 *
 * Source: https://html.spec.whatwg.org/entities.json
 *
 * CommonMark only recognizes the semicolon-terminated form, so the table keeps
 * those names and drops the legacy semicolon-less aliases. Entries are packed
 * into one string as `name=value` records separated by U+0001 to keep the
 * generated file (and the shipped bundle) small.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUTPUT = path.join(__dirname, '../src/entity_data.mbt');
const SOURCE_URL = 'https://html.spec.whatwg.org/entities.json';
const SEP = '\u0001';

function mbtEscape(s) {
  let out = '';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (code >= 0x20 && code < 0x7f) out += ch;
    else out += `\\u{${code.toString(16)}}`;
  }
  return out;
}

const response = await fetch(SOURCE_URL);
const entities = await response.json();

const names = Object.keys(entities)
  .filter((name) => name.endsWith(';'))
  .sort();

const records = names.map(
  (name) => `${name.slice(1, -1)}=${entities[name].characters}`
);

// Pack into chunks so no single source line grows unreadably long.
const CHUNK = 24;
const chunks = [];
for (let i = 0; i < records.length; i += CHUNK) {
  chunks.push(records.slice(i, i + CHUNK).join(SEP));
}

const body = chunks.map((chunk) => `  "${mbtEscape(chunk)}",`).join('\n');

const out = `///| HTML5 named character references, as required by CommonMark.
///|
///| Generated by \`scripts/gen-entities.js\` from
///| <https://html.spec.whatwg.org/entities.json>. Do not edit by hand.
///|
///| Each chunk holds \`name=value\` records separated by U+0001; \`entity.mbt\`
///| expands them into a lookup map the first time a reference is seen.

///|
/// ${names.length} semicolon-terminated named references, packed.
let entity_chunks : Array[String] = [
${body}
]
`;

fs.writeFileSync(OUTPUT, out);
console.log(`Wrote ${OUTPUT} (${names.length} entities, ${out.length} bytes)`);
